 21→// CopilotCLIAgent implements the Agent interface for GitHub Copilot CLI.
 22→//
 23→//nolint:revive // CopilotCLIAgent is clearer than Agent in this context
 24→type CopilotCLIAgent struct{}
 25→
 26→// NewCopilotCLIAgent creates a new Copilot CLI agent instance.
 27→func NewCopilotCLIAgent() agent.Agent {
 28→	return &CopilotCLIAgent{}
 29→}
 30→
 31→// Name returns the agent registry key.
 32→func (c *CopilotCLIAgent) Name() types.AgentName {
 33→	return agent.AgentNameCopilotCLI
 34→}
 35→
 36→// Type returns the agent type identifier.
 37→func (c *CopilotCLIAgent) Type() types.AgentType {
 38→	return agent.AgentTypeCopilotCLI
 39→}
 40→
 41→// Description returns a human-readable description.
 42→func (c *CopilotCLIAgent) Description() string {
 43→	return "Copilot CLI - GitHub's AI-powered coding agent"
 44→}
 45→
 46→// IsPreview returns true because this is a new integration.
 47→func (c *CopilotCLIAgent) IsPreview() bool { return true }
 48→
 49→// DetectPresence checks if Entire hooks are installed in the Copilot CLI config.
 50→// Delegates to AreHooksInstalled which checks .github/hooks/entire.json for Entire hook entries.
 51→func (c *CopilotCLIAgent) DetectPresence(ctx context.Context) (bool, error) {
 52→	return c.AreHooksInstalled(ctx), nil
 53→}
 54→
 55→// GetSessionID extracts the session ID from hook input.
 56→func (c *CopilotCLIAgent) GetSessionID(input *agent.HookInput) string {
 57→	return input.SessionID
 58→}
 59→
 60→// GetSessionDir returns the directory where Copilot CLI stores session transcripts.
 61→func (c *CopilotCLIAgent) GetSessionDir(_ string) (string, error) {
 62→	if override := os.Getenv("ENTIRE_TEST_COPILOT_SESSION_DIR"); override != "" {
 63→		return override, nil
 64→	}
 65→
 66→	homeDir, err := os.UserHomeDir()
 67→	if err != nil {
 68→		return "", fmt.Errorf("failed to get home directory: %w", err)
 69→	}
 70→
 71→	return filepath.Join(homeDir, ".copilot", "session-state"), nil
 72→}
 73→
 74→// ResolveSessionFile returns the path to a Copilot CLI session transcript file.
 75→// Copilot CLI stores transcripts at <sessionDir>/<sessionId>/events.jsonl.
 76→func (c *CopilotCLIAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 77→	return filepath.Join(sessionDir, agentSessionID, "events.jsonl")
 78→}
 79→
 80→// ProtectedDirs returns directories that Copilot CLI uses for config/state.
 81→func (c *CopilotCLIAgent) ProtectedDirs() []string {
 82→	return []string{filepath.Join(".github", "hooks")}
 83→}
 84→
 85→// ReadSession reads a session from Copilot CLI's storage (JSONL transcript file).
 86→func (c *CopilotCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
 87→	if input.SessionRef == "" {
 88→		return nil, errors.New("session reference (transcript path) is required")
 89→	}
 90→
 91→	data, err := os.ReadFile(input.SessionRef)
 92→	if err != nil {
 93→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 94→	}
 95→
 96→	return &agent.AgentSession{
 97→		SessionID:  input.SessionID,
 98→		AgentName:  c.Name(),
 99→		SessionRef: input.SessionRef,
100→		StartTime:  time.Now(),
101→		NativeData: data,
102→	}, nil
103→}
104→
105→// WriteSession writes a session to Copilot CLI's storage (JSONL transcript file).
106→func (c *CopilotCLIAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
107→	if session == nil {
108→		return errors.New("session is nil")
109→	}
110→
111→	if session.AgentName != "" && session.AgentName != c.Name() {
112→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
113→	}
114→
115→	if session.SessionRef == "" {
116→		return errors.New("session reference (transcript path) is required")
117→	}
118→
119→	if len(session.NativeData) == 0 {
120→		return errors.New("session has no native data to write")
121→	}
122→
123→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
124→		return fmt.Errorf("failed to write transcript: %w", err)
125→	}
126→
127→	return nil
128→}
129→
130→// FormatResumeCommand returns a command to resume a Copilot CLI session.
131→func (c *CopilotCLIAgent) FormatResumeCommand(sessionID string) string {
132→	return "copilot --resume " + sessionID
133→}
134→
135→// ReadTranscript reads the raw JSONL transcript bytes for a session.
136→func (c *CopilotCLIAgent) ReadTranscript(sessionRef string) ([]byte, error) {
137→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
138→	if err != nil {
139→		return nil, fmt.Errorf("failed to read transcript: %w", err)
140→	}
141→	return data, nil
142→}
143→
144→// ChunkTranscript splits a JSONL transcript at line boundaries.
145→func (c *CopilotCLIAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
146→	chunks, err := agent.ChunkJSONL(content, maxSize)
147→	if err != nil {
148→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
149→	}
150→	return chunks, nil
151→}
152→
153→// ReassembleTranscript concatenates JSONL chunks with newlines.
154→func (c *CopilotCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
155→	return agent.ReassembleJSONL(chunks), nil
156→}
