  1→package copilotcli
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"errors"
  7→	"fmt"
  8→	"os"
  9→	"path/filepath"
 10→	"strings"
 11→
 12→	"github.com/entireio/cli/cmd/entire/cli/agent"
 13→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 14→	"github.com/entireio/cli/cmd/entire/cli/logging"
 15→	"github.com/entireio/cli/cmd/entire/cli/paths"
 16→)
 17→
 18→// HooksFileName is the hooks file managed by Entire for Copilot CLI.
 19→const HooksFileName = "entire.json"
 20→
 21→// hooksDir is the directory within the repo where Copilot CLI looks for hook configs.
 22→const hooksDir = ".github/hooks"
 23→
 24→// entireHookPrefixes are command prefixes that identify Entire hooks in the bash field.
 25→var entireHookPrefixes = []string{
 26→	"entire ",
 27→	"go run ${COPILOT_PROJECT_DIR}/cmd/entire/main.go ",
 28→}
 29→
 30→// hookConfigKey maps our kebab-case hook names to camelCase JSON keys.
 31→var hookConfigKey = map[string]string{
 32→	HookNameUserPromptSubmitted: "userPromptSubmitted",
 33→	HookNameSessionStart:        "sessionStart",
 34→	HookNameAgentStop:           "agentStop",
 35→	HookNameSessionEnd:          "sessionEnd",
 36→	HookNameSubagentStop:        "subagentStop",
 37→	HookNamePreToolUse:          "preToolUse",
 38→	HookNamePostToolUse:         "postToolUse",
 39→	HookNameErrorOccurred:       "errorOccurred",
 40→}
 41→
 42→// InstallHooks installs Copilot CLI hooks in .github/hooks/entire.json.
 43→// If force is true, removes existing Entire hooks before installing.
 44→// Returns the number of hooks installed.
 45→// Unknown top-level fields and hook types are preserved on round-trip.
 46→func (c *CopilotCLIAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 47→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 48→	if err != nil {
 49→		worktreeRoot = "."
 50→	}
 51→
 52→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
 53→
 54→	// Use raw maps to preserve unknown fields on round-trip
 55→	var rawFile map[string]json.RawMessage
 56→	var rawHooks map[string]json.RawMessage
 57→
 58→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 59→	switch {
 60→	case readErr == nil:
 61→		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 62→			return 0, fmt.Errorf("failed to parse existing %s: %w", HooksFileName, err)
 63→		}
 64→		if hooksRaw, ok := rawFile["hooks"]; ok {
 65→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 66→				return 0, fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
 67→			}
 68→		}
 69→		if _, ok := rawFile["version"]; !ok {
 70→			rawFile["version"] = json.RawMessage(`1`)
 71→		}
 72→	case errors.Is(readErr, os.ErrNotExist):
 73→		rawFile = map[string]json.RawMessage{
 74→			"version": json.RawMessage(`1`),
 75→		}
 76→	default:
 77→		return 0, fmt.Errorf("failed to read %s: %w", HooksFileName, readErr)
 78→	}
 79→
 80→	if rawHooks == nil {
 81→		rawHooks = make(map[string]json.RawMessage)
 82→	}
 83→
 84→	// Parse existing entries for each hook type we manage
 85→	hookEntries := make(map[string][]CopilotHookEntry)
 86→	for _, hookName := range c.HookNames() {
 87→		key := hookConfigKey[hookName]
 88→		var entries []CopilotHookEntry
 89→		if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
 90→			return 0, fmt.Errorf("failed to parse %s hooks: %w", key, err)
 91→		}
 92→		hookEntries[hookName] = entries
 93→	}
 94→
 95→	// If force, remove existing Entire hooks first
 96→	if force {
 97→		for hookName, entries := range hookEntries {
 98→			hookEntries[hookName] = removeEntireHooks(entries)
 99→		}
100→	}
101→
102→	// Define command prefix
103→	var cmdPrefix string
104→	if localDev {
105→		cmdPrefix = "go run ${COPILOT_PROJECT_DIR}/cmd/entire/main.go hooks copilot-cli "
106→	} else {
107→		cmdPrefix = "entire hooks copilot-cli "
108→	}
109→
110→	count := 0
111→
112→	// Add hooks that don't already exist
113→	for _, hookName := range c.HookNames() {
114→		cmd := cmdPrefix + hookName
115→		entries := hookEntries[hookName]
116→		if !hookBashExists(entries, cmd) {
117→			entries = append(entries, CopilotHookEntry{
118→				Type:    "command",
119→				Bash:    cmd,
120→				Comment: "Entire CLI",
121→			})
122→			hookEntries[hookName] = entries
123→			count++
124→		}
125→	}
126→
127→	if count == 0 {
128→		return 0, nil
129→	}
130→
131→	// Marshal modified hook types back into rawHooks
132→	for _, hookName := range c.HookNames() {
133→		key := hookConfigKey[hookName]
134→		if err := marshalCopilotHookType(rawHooks, key, hookEntries[hookName]); err != nil {
135→			return 0, fmt.Errorf("failed to marshal %s hooks: %w", key, err)
136→		}
137→	}
138→
139→	// Marshal hooks and update raw file
140→	hooksJSON, err := json.Marshal(rawHooks)
141→	if err != nil {
142→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
143→	}
144→	rawFile["hooks"] = hooksJSON
145→
146→	// Write to file
147→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
148→		return 0, fmt.Errorf("failed to create %s directory: %w", hooksDir, err)
149→	}
150→
151→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
152→	if err != nil {
153→		return 0, fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
154→	}
155→
156→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
157→		return 0, fmt.Errorf("failed to write %s: %w", HooksFileName, err)
158→	}
159→
160→	return count, nil
161→}
162→
163→// UninstallHooks removes Entire hooks from Copilot CLI's entire.json.
164→// Unknown top-level fields and hook types are preserved on round-trip.
165→func (c *CopilotCLIAgent) UninstallHooks(ctx context.Context) error {
166→	worktreeRoot, err := paths.WorktreeRoot(ctx)
167→	if err != nil {
168→		worktreeRoot = "."
169→	}
170→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
171→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
172→	if err != nil {
173→		if errors.Is(err, os.ErrNotExist) {
174→			return nil // No hooks file means nothing to uninstall
175→		}
176→		return fmt.Errorf("failed to read %s: %w", HooksFileName, err)
177→	}
178→
179→	var rawFile map[string]json.RawMessage
180→	if err := json.Unmarshal(data, &rawFile); err != nil {
181→		return fmt.Errorf("failed to parse %s: %w", HooksFileName, err)
182→	}
183→
184→	var rawHooks map[string]json.RawMessage
185→	if hooksRaw, ok := rawFile["hooks"]; ok {
186→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
187→			return fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
188→		}
189→	}
190→	if rawHooks == nil {
191→		rawHooks = make(map[string]json.RawMessage)
192→	}
193→
194→	// Parse and remove Entire hooks from each hook type we manage
195→	for _, hookName := range c.HookNames() {
196→		key := hookConfigKey[hookName]
197→		var entries []CopilotHookEntry
198→		if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
199→			return fmt.Errorf("failed to parse %s hooks: %w", key, err)
200→		}
201→		entries = removeEntireHooks(entries)
202→		if err := marshalCopilotHookType(rawHooks, key, entries); err != nil {
203→			return fmt.Errorf("failed to marshal %s hooks: %w", key, err)
204→		}
205→	}
206→
207→	// Marshal hooks back (preserving unknown hook types)
208→	if len(rawHooks) > 0 {
209→		hooksJSON, err := json.Marshal(rawHooks)
210→		if err != nil {
211→			return fmt.Errorf("failed to marshal hooks: %w", err)
212→		}
213→		rawFile["hooks"] = hooksJSON
214→	} else {
215→		delete(rawFile, "hooks")
216→	}
217→
218→	// Write back
219→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
220→	if err != nil {
221→		return fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
222→	}
223→
224→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
225→		return fmt.Errorf("failed to write %s: %w", HooksFileName, err)
226→	}
227→	return nil
228→}
229→
230→// AreHooksInstalled checks if Entire hooks are installed in the Copilot CLI config.
231→func (c *CopilotCLIAgent) AreHooksInstalled(ctx context.Context) bool {
232→	worktreeRoot, err := paths.WorktreeRoot(ctx)
233→	if err != nil {
234→		worktreeRoot = "."
235→	}
236→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
237→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
238→	if err != nil {
239→		if !errors.Is(err, os.ErrNotExist) {
240→			logging.Warn(ctx, "copilot-cli: failed to read hooks file", "path", hooksPath, "err", err)
241→		}
242→		return false
243→	}
244→
245→	var hooksFile CopilotHooksFile
246→	if err := json.Unmarshal(data, &hooksFile); err != nil {
247→		logging.Warn(ctx, "copilot-cli: failed to parse hooks file", "path", hooksPath, "err", err)
248→		return false
249→	}
250→
251→	return hasEntireHook(hooksFile.Hooks.UserPromptSubmitted) ||
252→		hasEntireHook(hooksFile.Hooks.SessionStart) ||
253→		hasEntireHook(hooksFile.Hooks.AgentStop) ||
254→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
255→		hasEntireHook(hooksFile.Hooks.SubagentStop) ||
256→		hasEntireHook(hooksFile.Hooks.PreToolUse) ||
257→		hasEntireHook(hooksFile.Hooks.PostToolUse) ||
258→		hasEntireHook(hooksFile.Hooks.ErrorOccurred)
259→}
260→
261→// GetSupportedHooks returns the normalized lifecycle events this agent supports.
262→// Note: HookNames() returns 8 hooks (including preToolUse, postToolUse, errorOccurred),
263→// but GetSupportedHooks() returns only 6. The extra hooks are registered so `entire hooks install`
264→// sets them up, but ParseHookEvent returns nil for them (pass-through, no lifecycle action).
265→func (c *CopilotCLIAgent) GetSupportedHooks() []agent.HookType {
266→	return []agent.HookType{
267→		agent.HookSessionStart,
268→		agent.HookSessionEnd,
269→		agent.HookUserPromptSubmit,
270→		agent.HookStop,
271→		agent.HookPreToolUse,
272→		agent.HookPostToolUse,
273→	}
274→}
275→
276→// parseCopilotHookType parses a specific hook type from rawHooks into the target slice.
277→func parseCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CopilotHookEntry) error {
278→	if data, ok := rawHooks[hookType]; ok {
279→		if err := json.Unmarshal(data, target); err != nil {
280→			return fmt.Errorf("invalid JSON for hook type %s: %w", hookType, err)
281→		}
282→	}
283→	return nil
284→}
285→
286→// marshalCopilotHookType marshals a hook type back into rawHooks.
287→// If the slice is empty, removes the key from rawHooks.
288→func marshalCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CopilotHookEntry) error {
289→	if len(entries) == 0 {
290→		delete(rawHooks, hookType)
291→		return nil
292→	}
293→	data, err := json.Marshal(entries)
294→	if err != nil {
295→		return fmt.Errorf("failed to marshal hook type %s: %w", hookType, err)
296→	}
297→	rawHooks[hookType] = data
298→	return nil
299→}
300→
301→// hookBashExists checks if a hook with the given bash command already exists.
302→func hookBashExists(entries []CopilotHookEntry, bash string) bool {
303→	for _, entry := range entries {
304→		if entry.Bash == bash {
305→			return true
306→		}
307→	}
308→	return false
309→}
310→
311→// isEntireHook checks if a hook entry's bash command belongs to Entire.
312→func isEntireHook(bash string) bool {
313→	for _, prefix := range entireHookPrefixes {
314→		if strings.HasPrefix(bash, prefix) {
315→			return true
316→		}
317→	}
318→	return false
319→}
320→
321→// hasEntireHook checks if any entry in the slice is an Entire hook.
322→func hasEntireHook(entries []CopilotHookEntry) bool {
323→	for _, entry := range entries {
324→		if isEntireHook(entry.Bash) {
325→			return true
326→		}
327→	}
328→	return false
329→}
330→
331→// removeEntireHooks removes all Entire hooks from the slice.
332→func removeEntireHooks(entries []CopilotHookEntry) []CopilotHookEntry {
333→	result := make([]CopilotHookEntry, 0, len(entries))
334→	for _, entry := range entries {
335→		if !isEntireHook(entry.Bash) {
336→			result = append(result, entry)
337→		}
338→	}
339→	return result
340→}
