137→// extractPromptsFromEvents collects content from user.message events.
138→func extractPromptsFromEvents(events []copilotEvent) []string {
139→	var prompts []string
140→
141→	for i := range events {
142→		if events[i].Type != eventTypeUserMessage {
143→			continue
144→		}
145→
146→		var data userMessageData
147→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
148→			continue
149→		}
150→
151→		if data.Content != "" {
152→			prompts = append(prompts, data.Content)
153→		}
154→	}
155→
156→	return prompts
157→}
