159→// extractSummaryFromEvents returns the content of the last assistant.message event.
160→func extractSummaryFromEvents(events []copilotEvent) string {
161→	for i := len(events) - 1; i >= 0; i-- {
162→		if events[i].Type != eventTypeAssistantMsg {
163→			continue
164→		}
165→
166→		var data assistantMessageData
167→		if err := json.Unmarshal(events[i].Data, &data); err != nil {
168→			continue
169→		}
170→
171→		if data.Content != "" {
172→			return data.Content
173→		}
174→	}
175→
176→	return ""
177→}
