179→// GetTranscriptPosition returns the current line count of a Copilot CLI transcript.
180→// Copilot CLI uses JSONL format, so position is the number of lines.
181→// This is a lightweight operation that only counts lines without parsing JSON.
182→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
183→// Returns 0 if the file doesn't exist or is empty.
184→func (c *CopilotCLIAgent) GetTranscriptPosition(path string) (int, error) {
185→	if path == "" {
186→		return 0, nil
187→	}
188→
189→	file, err := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
190→	if err != nil {
191→		if os.IsNotExist(err) {
192→			return 0, nil
193→		}
194→		return 0, fmt.Errorf("failed to open transcript file: %w", err)
195→	}
196→	defer file.Close()
197→
198→	reader := bufio.NewReader(file)
199→	lineCount := 0
200→
201→	for {
202→		line, readErr := reader.ReadBytes('\n')
203→		if readErr != nil {
204→			if readErr == io.EOF {
205→				if len(line) > 0 {
206→					lineCount++ // Count final line without trailing newline
207→				}
208→				break
209→			}
210→			return 0, fmt.Errorf("failed to read transcript: %w", readErr)
211→		}
212→		lineCount++
213→	}
214→
215→	return lineCount, nil
216→}
217→
218→// ExtractModifiedFilesFromOffset extracts files modified since a given line number.
219→// For Copilot CLI (JSONL format), offset is the starting line number.
220→// Uses bufio.Reader to handle arbitrarily long lines (no size limit).
221→// Returns:
222→//   - files: list of file paths modified by Copilot (from tool.execution_complete events)
223→//   - currentPosition: total number of lines in the file
224→//   - error: any error encountered during reading
225→func (c *CopilotCLIAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
226→	if path == "" {
227→		return nil, 0, nil
228→	}
229→
230→	file, openErr := os.Open(path) //nolint:gosec // Path comes from Copilot CLI transcript location
231→	if openErr != nil {
232→		return nil, 0, fmt.Errorf("failed to open transcript file: %w", openErr)
233→	}
234→	defer file.Close()
235→
236→	reader := bufio.NewReader(file)
237→	var events []copilotEvent
238→	lineNum := 0
239→
240→	for {
241→		lineData, readErr := reader.ReadBytes('\n')
242→		if readErr != nil && readErr != io.EOF {
243→			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
244→		}
245→
246→		if len(lineData) > 0 {
247→			lineNum++
248→			if lineNum > startOffset {
249→				var ev copilotEvent
250→				if parseErr := json.Unmarshal(lineData, &ev); parseErr == nil {
251→					events = append(events, ev)
252→				}
253→				// Skip malformed lines silently
254→			}
255→		}
256→
257→		if readErr == io.EOF {
258→			break
259→		}
260→	}
261→
262→	return extractModifiedFilesFromEvents(events), lineNum, nil
263→}
264→
265→// ExtractPrompts extracts user prompts from the transcript starting at the given offset.
266→func (c *CopilotCLIAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
267→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
268→	if err != nil {
269→		return nil, fmt.Errorf("failed to read transcript: %w", err)
270→	}
271→
272→	events, err := parseEventsFromOffset(data, fromOffset)
273→	if err != nil {
274→		return nil, fmt.Errorf("failed to parse transcript events: %w", err)
275→	}
276→	return extractPromptsFromEvents(events), nil
277→}
