279→// ExtractSummary extracts the last assistant message as a session summary.
280→func (c *CopilotCLIAgent) ExtractSummary(sessionRef string) (string, error) {
281→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
282→	if err != nil {
283→		return "", fmt.Errorf("failed to read transcript: %w", err)
284→	}
285→
286→	events, err := parseEventsFromBytes(data)
287→	if err != nil {
288→		return "", fmt.Errorf("failed to parse transcript events: %w", err)
289→	}
290→	return extractSummaryFromEvents(events), nil
291→}
