166→// UninstallHooks removes Entire hooks from Copilot CLI's entire.json.
167→// Unknown top-level fields and hook types are preserved on round-trip.
168→func (c *CopilotCLIAgent) UninstallHooks(ctx context.Context) error {
169→	worktreeRoot, err := paths.WorktreeRoot(ctx)
170→	if err != nil {
171→		worktreeRoot = "."
172→	}
173→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
174→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
175→	if err != nil {
176→		if errors.Is(err, os.ErrNotExist) {
177→			return nil // No hooks file means nothing to uninstall
178→		}
179→		return fmt.Errorf("failed to read %s: %w", HooksFileName, err)
180→	}
181→
182→	var rawFile map[string]json.RawMessage
183→	if err := json.Unmarshal(data, &rawFile); err != nil {
184→		return fmt.Errorf("failed to parse %s: %w", HooksFileName, err)
185→	}
186→
187→	var rawHooks map[string]json.RawMessage
188→	if hooksRaw, ok := rawFile["hooks"]; ok {
189→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
190→			return fmt.Errorf("failed to parse hooks in %s: %w", HooksFileName, err)
191→		}
192→	}
193→	if rawHooks == nil {
194→		rawHooks = make(map[string]json.RawMessage)
195→	}
196→
197→	// Parse and remove Entire hooks from each hook type we manage
198→	for _, hookName := range c.HookNames() {
199→		key := hookConfigKey[hookName]
200→		var entries []CopilotHookEntry
201→		if err := parseCopilotHookType(rawHooks, key, &entries); err != nil {
202→			return fmt.Errorf("failed to parse %s hooks: %w", key, err)
203→		}
204→		entries = removeEntireHooks(entries)
205→		if err := marshalCopilotHookType(rawHooks, key, entries); err != nil {
206→			return fmt.Errorf("failed to marshal %s hooks: %w", key, err)
207→		}
208→	}
209→
210→	// Marshal hooks back (preserving unknown hook types)
211→	if len(rawHooks) > 0 {
212→		hooksJSON, err := json.Marshal(rawHooks)
213→		if err != nil {
214→			return fmt.Errorf("failed to marshal hooks: %w", err)
215→		}
216→		rawFile["hooks"] = hooksJSON
217→	} else {
218→		delete(rawFile, "hooks")
219→	}
220→
221→	// Write back
222→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
223→	if err != nil {
224→		return fmt.Errorf("failed to marshal %s: %w", HooksFileName, err)
225→	}
226→
227→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
228→		return fmt.Errorf("failed to write %s: %w", HooksFileName, err)
229→	}
230→	return nil
231→}
