233→// AreHooksInstalled checks if Entire hooks are installed in the Copilot CLI config.
234→func (c *CopilotCLIAgent) AreHooksInstalled(ctx context.Context) bool {
235→	worktreeRoot, err := paths.WorktreeRoot(ctx)
236→	if err != nil {
237→		worktreeRoot = "."
238→	}
239→	hooksPath := filepath.Join(worktreeRoot, hooksDir, HooksFileName)
240→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
241→	if err != nil {
242→		if !errors.Is(err, os.ErrNotExist) {
243→			logging.Warn(ctx, "copilot-cli: failed to read hooks file", "path", hooksPath, "err", err)
244→		}
245→		return false
246→	}
247→
248→	var hooksFile CopilotHooksFile
249→	if err := json.Unmarshal(data, &hooksFile); err != nil {
250→		logging.Warn(ctx, "copilot-cli: failed to parse hooks file", "path", hooksPath, "err", err)
251→		return false
252→	}
253→
254→	return hasEntireHook(hooksFile.Hooks.UserPromptSubmitted) ||
255→		hasEntireHook(hooksFile.Hooks.SessionStart) ||
256→		hasEntireHook(hooksFile.Hooks.AgentStop) ||
257→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
258→		hasEntireHook(hooksFile.Hooks.SubagentStop) ||
259→		hasEntireHook(hooksFile.Hooks.PreToolUse) ||
260→		hasEntireHook(hooksFile.Hooks.PostToolUse) ||
261→		hasEntireHook(hooksFile.Hooks.ErrorOccurred)
262→}
