264→// GetSupportedHooks returns the normalized lifecycle events this agent supports.
265→// Note: HookNames() returns 8 hooks but GetSupportedHooks() returns only 6.
266→// The two not listed here are:
267→//   - subagentStop: handled by ParseHookEvent (returns SubagentEnd), but there is no
268→//     HookType constant for subagent events (they use EventType instead).
269→//   - errorOccurred: pass-through hook with no lifecycle action (ParseHookEvent returns nil).
270→func (c *CopilotCLIAgent) GetSupportedHooks() []agent.HookType {
271→	return []agent.HookType{
272→		agent.HookSessionStart,
273→		agent.HookSessionEnd,
274→		agent.HookUserPromptSubmit,
275→		agent.HookStop,
276→		agent.HookPreToolUse,
277→		agent.HookPostToolUse,
278→	}
279→}
