281→// parseCopilotHookType parses a specific hook type from rawHooks into the target slice.
282→func parseCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CopilotHookEntry) error {
283→	if data, ok := rawHooks[hookType]; ok {
284→		if err := json.Unmarshal(data, target); err != nil {
285→			return fmt.Errorf("invalid JSON for hook type %s: %w", hookType, err)
286→		}
287→	}
288→	return nil
289→}
290→
291→// marshalCopilotHookType marshals a hook type back into rawHooks.
292→// If the slice is empty, removes the key from rawHooks.
293→func marshalCopilotHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CopilotHookEntry) error {
294→	if len(entries) == 0 {
295→		delete(rawHooks, hookType)
296→		return nil
297→	}
298→	data, err := json.Marshal(entries)
299→	if err != nil {
300→		return fmt.Errorf("failed to marshal hook type %s: %w", hookType, err)
301→	}
302→	rawHooks[hookType] = data
303→	return nil
304→}
305→
306→// hookBashExists checks if a hook with the given bash command already exists.
307→func hookBashExists(entries []CopilotHookEntry, bash string) bool {
308→	for _, entry := range entries {
309→		if entry.Bash == bash {
310→			return true
311→		}
312→	}
313→	return false
314→}
315→
316→// isEntireHook checks if a hook entry's bash command belongs to Entire.
317→func isEntireHook(bash string) bool {
318→	for _, prefix := range entireHookPrefixes {
319→		if strings.HasPrefix(bash, prefix) {
320→			return true
321→		}
322→	}
323→	return false
324→}
325→
326→// hasEntireHook checks if any entry in the slice is an Entire hook.
327→func hasEntireHook(entries []CopilotHookEntry) bool {
328→	for _, entry := range entries {
329→		if isEntireHook(entry.Bash) {
330→			return true
331→		}
332→	}
333→	return false
334→}
335→
336→// removeEntireHooks removes all Entire hooks from the slice.
337→func removeEntireHooks(entries []CopilotHookEntry) []CopilotHookEntry {
338→	result := make([]CopilotHookEntry, 0, len(entries))
339→	for _, entry := range entries {
340→		if !isEntireHook(entry.Bash) {
341→			result = append(result, entry)
342→		}
343→	}
344→	return result
345→}
