func TestInstallHooks_LocalDev(t *testing.T) {
	tempDir := t.TempDir()
	t.Chdir(tempDir)

	ag := &CopilotCLIAgent{}
	_, err := ag.InstallHooks(context.Background(), true, false)
	if err != nil {
		t.Fatalf("InstallHooks(localDev=true) error = %v", err)
	}

	hooksFile := readHooksFile(t, tempDir)
	expectedBash := "go run ${ENTIRE_DEV_DIR}/cmd/entire/main.go hooks copilot-cli agent-stop"
	assertEntryBash(t, hooksFile.Hooks.AgentStop, expectedBash)

	// Verify the env field injects ENTIRE_DEV_DIR
	for _, entry := range hooksFile.Hooks.AgentStop {
		if entry.Bash == expectedBash {
			if entry.Env == nil || entry.Env["ENTIRE_DEV_DIR"] == "" {
				t.Error("localDev hook entry should have ENTIRE_DEV_DIR in env field")
			}
			return
		}
	}
	t.Error("localDev hook entry not found")
}
